DROP TABLE IF EXISTS city_region_q;
CREATE TABLE city_region_q (city TEXT PRIMARY KEY, region TEXT NOT NULL);
INSERT INTO city_region_q (city, region) VALUES ('Mumbai','West'), ('Delhi','North'), ('Chennai','South'), ('Kolkata','East'), ('Pune','West');
SELECT city, region FROM city_region_q ORDER BY city;

DROP TABLE IF EXISTS budget_copy_q;
CREATE TABLE budget_copy_q AS SELECT campaign_id, channel, budget_inr FROM campaigns;
UPDATE budget_copy_q SET budget_inr = budget_inr * 1.10 WHERE channel = 'Google Search';
SELECT channel, ROUND(SUM(budget_inr), 2) AS total_budget_inr FROM budget_copy_q GROUP BY channel ORDER BY channel;

DROP VIEW IF EXISTS v_big_delivered_q;
CREATE VIEW v_big_delivered_q AS SELECT DISTINCT order_id, customer_id, total_amount FROM orders WHERE order_status = 'Delivered' AND total_amount >= 20000;
SELECT COUNT(*) AS orders, ROUND(AVG(total_amount), 2) AS avg_amount FROM v_big_delivered_q;

DROP TABLE IF EXISTS accounts_q;
CREATE TABLE accounts_q (acct TEXT PRIMARY KEY, balance_inr REAL NOT NULL CHECK (balance_inr >= 0));
INSERT INTO accounts_q VALUES ('Meera', 8000), ('Sameer', 2500), ('Tanvi', 0);
BEGIN;
UPDATE accounts_q SET balance_inr = balance_inr - 4500 WHERE acct = 'Meera';
UPDATE accounts_q SET balance_inr = balance_inr + 3000 WHERE acct = 'Sameer';
UPDATE accounts_q SET balance_inr = balance_inr + 1500 WHERE acct = 'Tanvi';
COMMIT;
BEGIN;
UPDATE accounts_q SET balance_inr = balance_inr - 500 WHERE acct = 'Tanvi';
UPDATE accounts_q SET balance_inr = balance_inr + 500 WHERE acct = 'Meera';
ROLLBACK;
SELECT acct, balance_inr FROM accounts_q ORDER BY acct;

DROP TABLE IF EXISTS employees_dedup_q;
CREATE TABLE employees_dedup_q AS SELECT * FROM employees;
DELETE FROM employees_dedup_q WHERE rowid NOT IN (SELECT MIN(rowid) FROM employees_dedup_q GROUP BY employee_id);
SELECT COUNT(*) AS rows_after, COUNT(DISTINCT employee_id) AS unique_ids, (SELECT COUNT(*) FROM employees) - COUNT(*) AS rows_removed FROM employees_dedup_q;
